changeSet.sql:
UPDATE billing_ledger SET payment_method = 'CLICK'
 WHERE entry_type = 'TOP_UP' AND payment_method IS NULL AND description = 'Пополнение через Click';
UPDATE billing_ledger SET payment_method = 'PAYME'
 WHERE entry_type = 'TOP_UP' AND payment_method IS NULL AND description = 'Пополнение через Payme';
UPDATE billing_ledger SET payment_method = 'BANK_TRANSFER'
 WHERE entry_type = 'TOP_UP' AND payment_method IS NULL AND description LIKE 'Пополнение по заявке %';
UPDATE billing_ledger SET payment_method = 'OTHER'
 WHERE entry_type = 'TOP_UP' AND payment_method IS NULL;
